package com.eduflow.service;
import com.eduflow.dto.AcademicDtos.*; import com.eduflow.entity.*; import com.eduflow.exception.EduFlowException;
import com.eduflow.repository.*; import com.eduflow.security.TenantRlsContext; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service @RequiredArgsConstructor
public class AcademicService {
 private final CenterRepository centers; private final TeacherRepository teachers; private final CourseRepository courses; private final StudyGroupRepository groups; private final LessonRepository lessons; private final StudentRepository students; private final AttendanceRepository attendance; private final GradeRepository grades; private final TenantRlsContext tenantRlsContext; private final NotificationService notificationService; private final GroupEnrollmentRepository enrollments; private final CenterMembershipRepository memberships; private final RefreshTokenRepository refreshTokens;
 private Center center(Long id){if(id==null)throw fail(HttpStatus.BAD_REQUEST,"tenant.context.required");tenantRlsContext.apply(id);Center c=centers.findById(id).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"center.not-found"));if(c.getStatus()!=CenterStatus.ACTIVE)throw fail(HttpStatus.FORBIDDEN,"tenant.center.inactive");return c;}
 private EduFlowException fail(HttpStatus s,String code){return new EduFlowException(s,code);}
 private String clean(String s){return s==null||s.isBlank()?null:s.trim();}
 @Transactional(readOnly=true) public List<Teacher> teachers(Long c){center(c);return teachers.findAllByCenter_IdAndStatusOrderByLastNameAscFirstNameAsc(c,"ACTIVE");}
 @Transactional public Teacher addTeacher(Long c,TeacherRequest r){Center x=center(c);String code=r.teacherCode().trim();if(teachers.existsByCenter_IdAndTeacherCode(c,code))throw fail(HttpStatus.CONFLICT,"teacher.code.exists");return teachers.save(new Teacher(x,code,r.firstName().trim(),r.lastName().trim(),clean(r.email()),clean(r.phone()),clean(r.specialization())));}
 @Transactional public Teacher updateTeacher(Long c,Long id,TeacherRequest r){center(c);Teacher t=teachers.findByIdAndCenter_Id(id,c).filter(x->"ACTIVE".equals(x.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"teacher.not-found"));String code=r.teacherCode().trim();if(teachers.existsByCenter_IdAndTeacherCodeAndIdNot(c,code,id))throw fail(HttpStatus.CONFLICT,"teacher.code.exists");t.setTeacherCode(code);t.setFirstName(r.firstName().trim());t.setLastName(r.lastName().trim());t.setEmail(clean(r.email()));t.setPhone(clean(r.phone()));t.setSpecialization(clean(r.specialization()));return t;}
 @Transactional public void deactivateTeacher(Long c,Long id){center(c);Teacher t=teachers.findByIdAndCenter_Id(id,c).filter(x->"ACTIVE".equals(x.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"teacher.not-found"));t.setStatus("INACTIVE");if(t.getUser()!=null){User user=t.getUser();user.setEnabled(false);user.setStatus(UserStatus.INACTIVE);memberships.findByCenterIdAndUserId(c,user.getId()).ifPresent(m->m.setStatus(MembershipStatus.INACTIVE));tenantRlsContext.applyUser(user.getId());refreshTokens.deleteByUserId(user.getId());}}
 @Transactional(readOnly=true) public List<Course> courses(Long c){center(c);return courses.findAllByCenter_IdAndActiveTrueOrderByNameAsc(c);}
 @Transactional public Course addCourse(Long c,CourseRequest r){Center x=center(c);String code=r.courseCode().trim();if(courses.existsByCenter_IdAndCourseCode(c,code))throw fail(HttpStatus.CONFLICT,"course.code.exists");return courses.save(new Course(x,code,r.name().trim(),clean(r.description())));}
 @Transactional public Course updateCourse(Long c,Long id,CourseRequest r){center(c);Course x=courses.findByIdAndCenter_IdAndActiveTrue(id,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"course.not-found"));String code=r.courseCode().trim();if(courses.existsByCenter_IdAndCourseCodeAndIdNot(c,code,id))throw fail(HttpStatus.CONFLICT,"course.code.exists");x.setCourseCode(code);x.setName(r.name().trim());x.setDescription(clean(r.description()));return x;}
 @Transactional public void deactivateCourse(Long c,Long id){center(c);Course x=courses.findByIdAndCenter_IdAndActiveTrue(id,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"course.not-found"));if(groups.existsByCenter_IdAndCourse_IdAndActiveTrue(c,id))throw fail(HttpStatus.CONFLICT,"course.has-active-groups");x.setActive(false);}
 @Transactional(readOnly=true) public List<StudyGroup> groups(Long c){center(c);return groups.findAllByCenter_IdAndActiveTrueOrderByNameAsc(c);}
 @Transactional public StudyGroup addGroup(Long c,GroupRequest r){Center x=center(c);validateDates(r.startsOn(),r.endsOn());String code=r.groupCode().trim();if(groups.existsByCenter_IdAndGroupCode(c,code))throw fail(HttpStatus.CONFLICT,"group.code.exists");Course course=courses.findByIdAndCenter_IdAndActiveTrue(r.courseId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"course.not-found"));Teacher teacher=teachers.findByIdAndCenter_Id(r.teacherId(),c).filter(t->"ACTIVE".equals(t.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"teacher.not-found"));return groups.save(new StudyGroup(x,course,teacher,code,r.name().trim(),r.startsOn(),r.endsOn()));}
 @Transactional public StudyGroup updateGroup(Long c,Long id,GroupRequest r){center(c);validateDates(r.startsOn(),r.endsOn());StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(id,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));String code=r.groupCode().trim();if(groups.existsByCenter_IdAndGroupCodeAndIdNot(c,code,id))throw fail(HttpStatus.CONFLICT,"group.code.exists");Course course=courses.findByIdAndCenter_IdAndActiveTrue(r.courseId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"course.not-found"));Teacher teacher=teachers.findByIdAndCenter_Id(r.teacherId(),c).filter(t->"ACTIVE".equals(t.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"teacher.not-found"));g.setCourse(course);g.setTeacher(teacher);g.setGroupCode(code);g.setName(r.name().trim());g.setStartsOn(r.startsOn());g.setEndsOn(r.endsOn());return g;}
 @Transactional public void deactivateGroup(Long c,Long id){center(c);StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(id,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));g.setActive(false);}
 private void validateDates(java.time.LocalDate start,java.time.LocalDate end){if(start!=null&&end!=null&&end.isBefore(start))throw fail(HttpStatus.BAD_REQUEST,"group.date.invalid");}
 @Transactional public GroupEnrollment enrollStudent(Long c,Long groupId,Long studentId){Center x=center(c);StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(groupId,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));Student s=students.findByIdAndCenter_Id(studentId,c).filter(v->v.getStatus()==StudentStatus.ACTIVE).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"student.not-found"));if(enrollments.existsByCenter_IdAndGroup_IdAndStudent_IdAndActiveTrue(c,groupId,studentId))throw fail(HttpStatus.CONFLICT,"group.student.exists");return enrollments.save(new GroupEnrollment(x,g,s));}
 @Transactional(readOnly=true) public List<GroupEnrollment> groupEnrollments(Long c,Long groupId){center(c);groups.findByIdAndCenter_IdAndActiveTrue(groupId,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));return enrollments.findAllByCenter_IdAndGroup_IdAndActiveTrueOrderByStudent_LastNameAsc(c,groupId);}
 @Transactional(readOnly=true) public List<Lesson> lessons(Long c,Long g){center(c);groups.findByIdAndCenter_IdAndActiveTrue(g,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));return lessons.findAllByCenter_IdAndGroup_IdOrderByStartsAtAsc(c,g);}
 @Transactional public Lesson addLesson(Long c,LessonRequest r){Center x=center(c);validateLessonTimes(r.startsAt(),r.endsAt());StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(r.groupId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));return lessons.save(new Lesson(x,g,r.title().trim(),clean(r.description()),r.startsAt(),r.endsAt()));}
 @Transactional public Lesson updateLesson(Long c,Long id,LessonRequest r){center(c);validateLessonTimes(r.startsAt(),r.endsAt());Lesson l=lessons.findByIdAndCenter_Id(id,c).filter(x->!"CANCELLED".equals(x.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"lesson.not-found"));StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(r.groupId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));l.setGroup(g);l.setTitle(r.title().trim());l.setDescription(clean(r.description()));l.setStartsAt(r.startsAt());l.setEndsAt(r.endsAt());return l;}
 @Transactional public void cancelLesson(Long c,Long id){center(c);Lesson l=lessons.findByIdAndCenter_Id(id,c).filter(x->!"CANCELLED".equals(x.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"lesson.not-found"));l.setStatus("CANCELLED");}
 private void validateLessonTimes(java.time.LocalDateTime start,java.time.LocalDateTime end){if(start==null||end==null||!end.isAfter(start))throw fail(HttpStatus.BAD_REQUEST,"lesson.time.invalid");}
 @Transactional public AttendanceRecord markAttendance(Long c,AttendanceRequest r){Center x=center(c);String status=r.status().trim().toUpperCase(Locale.ROOT);if(!Set.of("PRESENT","ABSENT","LATE","EXCUSED").contains(status))throw fail(HttpStatus.BAD_REQUEST,"attendance.status.invalid");Lesson l=lessons.findByIdAndCenter_Id(r.lessonId(),c).filter(v->!"CANCELLED".equals(v.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"lesson.not-found"));Student s=students.findByIdAndCenter_Id(r.studentId(),c).filter(v->v.getStatus()==StudentStatus.ACTIVE).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"student.not-found"));if(!enrollments.existsByCenter_IdAndGroup_IdAndStudent_IdAndActiveTrue(c,l.getGroup().getId(),s.getId()))throw fail(HttpStatus.CONFLICT,"student.not-enrolled");AttendanceRecord saved=attendance.findByCenter_IdAndLesson_IdAndStudent_Id(c,l.getId(),s.getId()).map(existing->{existing.setStatus(status);existing.setNote(clean(r.note()));return attendance.save(existing);}).orElseGet(()->attendance.save(new AttendanceRecord(x,l,s,status,clean(r.note()))));notificationService.notifyStudentParents(c,s.getId(),"ATTENDANCE","Davomat yangilandi",s.getFirstName()+" "+s.getLastName()+": "+status);return saved;}
 @Transactional(readOnly=true) public List<AttendanceRecord> attendance(Long c,Long lesson){center(c);lessons.findByIdAndCenter_Id(lesson,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"lesson.not-found"));return attendance.findAllByCenter_IdAndLesson_IdOrderByStudent_LastNameAsc(c,lesson);}
 @Transactional public GradeRecord addGrade(Long c,GradeRequest r){Center x=center(c);if(r.score().compareTo(r.maxScore())>0)throw fail(HttpStatus.BAD_REQUEST,"grade.score.invalid");Student s=students.findByIdAndCenter_Id(r.studentId(),c).filter(v->v.getStatus()==StudentStatus.ACTIVE).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"student.not-found"));StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(r.groupId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));if(!enrollments.existsByCenter_IdAndGroup_IdAndStudent_IdAndActiveTrue(c,g.getId(),s.getId()))throw fail(HttpStatus.CONFLICT,"student.not-enrolled");GradeRecord saved=grades.save(new GradeRecord(x,s,g,r.title().trim(),r.score(),r.maxScore(),clean(r.comment())));notificationService.notifyStudentParents(c,s.getId(),"GRADE","Yangi baho",s.getFirstName()+" "+s.getLastName()+": "+r.title().trim()+" — "+r.score()+"/"+r.maxScore());return saved;}
 @Transactional(readOnly=true) public List<GradeRecord> grades(Long c,Long student){center(c);students.findByIdAndCenter_Id(student,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"student.not-found"));return grades.findAllByCenter_IdAndStudent_IdOrderByCreatedAtDesc(c,student);}
}